import sys

def main():
    n = int(sys.stdin.read().strip())
    print(f(n))

def f(n):
    Len = int(4e5)
    pi_upper = [0] * Len
    pi_lower = [0] * Len
    for i in range(1, Len):
        pi_lower[i] = i
        pi_upper[i] = n // i
    isPrime = [True] * Len
    isPrime[0] = False
    isPrime[1] = False

    primeList = []
    for i in range(2, Len):
        if not isPrime[i]:
            continue
        primeList.append(i)
        for j in range(i * 2, Len, i):
            isPrime[j] = False

    for t, p in enumerate(primeList):
        p_sq = p * p
        for i in range(1, Len):
            if n // i < p_sq:
                break
            if i * p < Len:
                pi_upper[i] -= pi_upper[i * p]
            else:
                pi_upper[i] -= pi_lower[n // (i * p)]
        for i in range(Len - 1, p_sq - 1, -1):
            pi_lower[i] -= pi_lower[i // p] - (t + 1)

    ans = 0
    for p in primeList:
        if p * p > n:
            break
        if p * p * p <= n and p * p * p > 0:
            ans += 1
        if n // p > p:
            if p < Len:
                ans += pi_upper[p] - pi_lower[p]
            else:
                ans += pi_lower[n // p] - pi_lower[p]
    return ans

if __name__ == "__main__":
    main()

